using System.Globalization;
using Amazon.S3;
using Amazon.S3.Model;

namespace TroViec.Api.Infrastructure.Storage;

/// <summary>S3__Bucket* (docs/08-deployment.md). Listing images are public via Caddy; the others are private.</summary>
public sealed class StorageBuckets
{
    public string ListingImages { get; set; } = "listing-images";
    public string ScanImages { get; set; } = "scan-images";
    public string OwnerDocuments { get; set; } = "owner-documents";
}

/// <summary>Object keys are generated by the server, never from user file names (docs/07-security.md).</summary>
public static class ObjectKeys
{
    public static string ListingImage(Guid listingPublicId) => $"{listingPublicId:D}/{Guid.NewGuid():N}.webp";

    public static string ScanImage(Guid scanPublicId, int imageNo) =>
        $"{scanPublicId:D}/{imageNo.ToString(CultureInfo.InvariantCulture)}.webp";

    public static string OwnerDocument(long ownerUserId) =>
        $"{ownerUserId.ToString(CultureInfo.InvariantCulture)}/{Guid.NewGuid():N}.bin";
}

public interface IObjectStorage
{
    Task PutAsync(string bucket, string key, byte[] content, string contentType, CancellationToken ct);

    /// <summary>The object's bytes, or null when it does not exist.</summary>
    Task<byte[]?> GetAsync(string bucket, string key, CancellationToken ct);

    Task<bool> ExistsAsync(string bucket, string key, CancellationToken ct);

    /// <summary>Idempotent: deleting a missing object is not an error.</summary>
    Task DeleteAsync(string bucket, string key, CancellationToken ct);
}

/// <summary>Garage through the S3 API (path-style; client configured in ServiceSetup.AddObjectStorage).</summary>
public sealed class S3ObjectStorage(IAmazonS3 s3) : IObjectStorage
{
    public async Task PutAsync(string bucket, string key, byte[] content, string contentType, CancellationToken ct)
    {
        using var body = new MemoryStream(content, writable: false);
        await s3.PutObjectAsync(new PutObjectRequest
        {
            BucketName = bucket,
            Key = key,
            InputStream = body,
            ContentType = contentType,
            AutoCloseStream = false,
            UseChunkEncoding = false,  // Garage does not accept aws-chunked uploads
        }, ct);
    }

    public async Task<byte[]?> GetAsync(string bucket, string key, CancellationToken ct)
    {
        try
        {
            using var response = await s3.GetObjectAsync(bucket, key, ct);
            using var buffer = new MemoryStream();
            await response.ResponseStream.CopyToAsync(buffer, ct);
            return buffer.ToArray();
        }
        catch (AmazonS3Exception ex) when (ex.StatusCode == System.Net.HttpStatusCode.NotFound)
        {
            return null;
        }
    }

    public async Task<bool> ExistsAsync(string bucket, string key, CancellationToken ct)
    {
        try
        {
            await s3.GetObjectMetadataAsync(bucket, key, ct);
            return true;
        }
        catch (AmazonS3Exception ex) when (ex.StatusCode == System.Net.HttpStatusCode.NotFound)
        {
            return false;
        }
    }

    public Task DeleteAsync(string bucket, string key, CancellationToken ct) => s3.DeleteObjectAsync(bucket, key, ct);
}

public static class StorageSetup
{
    public static IServiceCollection AddStorage(this IServiceCollection services, IConfiguration configuration)
    {
        services.AddOptions<StorageBuckets>().Configure<IConfiguration>((buckets, config) =>
        {
            var s3 = config.GetSection("S3");
            buckets.ListingImages = s3["BucketListingImages"] ?? buckets.ListingImages;
            buckets.ScanImages = s3["BucketScanImages"] ?? buckets.ScanImages;
            buckets.OwnerDocuments = s3["BucketOwnerDocuments"] ?? buckets.OwnerDocuments;
        });
        services.AddSingleton<IObjectStorage, S3ObjectStorage>();
        return services;
    }
}
